CREATE OR REPLACE FUNCTION questions_search_vector_trigger() RETURNS trigger AS $$
BEGIN
  NEW.search_vector := to_tsvector('english', coalesce(NEW.title, '') || ' ' || coalesce(NEW.body, ''));
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_questions_search_vector
BEFORE INSERT OR UPDATE OF title, body ON questions
FOR EACH ROW EXECUTE FUNCTION questions_search_vector_trigger();
